parameters.jsCode:
return [{
  json: {
    event_type: 'lead.created',
    entity_type: 'lead',
    entity_id: 'demo-lead-001',
    dealer_id: 'dealer-demo-001',
    vehicle_id: 'vehicle-demo-911',
    source: 'black-label-market-demo',
    created_at: new Date().toISOString(),
    data: {
      contact: {
        name: 'Cliente Demo',
        email: 'cliente@example.com',
        phone: '+34 600 000 000'
      },
      brand: 'Porsche',
      model: '911 GT3 Touring',
      budget: '180000',
      timeline: '0-30 dias',
      message: 'Estoy interesado en esta unidad y quiero coordinar una visita.'
    }
  }
}];

const input = $json || {};
const body = input.body && Object.keys(input.body).length ? input.body : input;
const headers = input.headers || {};
const env = typeof $env !== 'undefined' ? $env : {};
const expectedSecret = env.BSM_N8N_WEBHOOK_SECRET || '';
const incomingSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.webhook_secret || '';

if (expectedSecret && incomingSecret !== expectedSecret) {
  return [{
    json: {
      ok: false,
      event_type: 'security.rejected',
      status: 'rejected',
      reason: 'invalid_webhook_secret',
      demo_visible_message: 'Solicitud rechazada: el secreto del webhook no coincide.'
    }
  }];
}

const data = body.data || body.payload?.data || body.payload || {};
const contact = data.contact || body.contact || {};
const eventType = body.event_type || body.eventType || 'unknown.event';

const normalized = {
  ok: true,
  event_type: eventType,
  entity_type: body.entity_type || body.entityType || null,
  entity_id: body.entity_id || body.entityId || null,
  dealer_id: body.dealer_id || body.dealerId || null,
  vehicle_id: body.vehicle_id || body.vehicleId || data.vehicle_id || null,
  source: body.source || 'black-label-market',
  received_at: new Date().toISOString(),
  contact: {
    name: contact.name || body.buyer_name || null,
    email: contact.email || body.buyer_email || null,
    phone: contact.phone || body.buyer_phone || null
  },
  vehicle: {
    brand: data.brand || body.brand || null,
    model: data.model || body.model || null,
    year: data.year || body.year || null,
    budget: data.budget || data.budget_max || body.budget || null,
    timeline: data.timeline || data.timeframe || body.timeline || null
  },
  raw_data: data,
  original_event: body
};

return [{ json: normalized }];

return [{ json: {
  ok: false,
  route: 'security',
  status_code: 401,
  title: 'Webhook rechazado',
  client_demo_summary: 'El workflow protege la entrada validando un secreto compartido antes de procesar datos comerciales.',
  actions: [
    'No crear lead',
    'No avisar al equipo comercial',
    'Registrar intento rechazado para auditoria'
  ],
  received_event: $json
}}];

return [{ json: {
  ok: true,
  route: 'private_search',
  title: 'Solicitud de vehiculo a la carta',
  client_demo_summary: 'Una busqueda privada se convierte en una oportunidad interna para Black Series y en senal de demanda para captar inventario.',
  demand_signal: {
    desired_vehicle: $json.vehicle,
    contact: $json.contact,
    source: $json.source,
    tags: ['vehiculo-a-la-carta', $json.vehicle?.brand, $json.vehicle?.model].filter(Boolean)
  },
  actions: [
    'Crear oportunidad interna Black Series',
    'Asignar responsable de sourcing',
    'Buscar matches en inventario actual',
    'Notificar si aparece una unidad compatible'
  ],
  received_event: $json
}}];

return [{ json: {
  ok: true,
  route: 'search_alert',
  title: 'Nueva alerta guardada',
  client_demo_summary: 'La alerta guarda demanda futura y permite avisar automaticamente cuando entra inventario compatible.',
  alert_segment: {
    email: $json.contact?.email,
    vehicle: $json.vehicle,
    tags: ['alerta-busqueda', $json.vehicle?.brand, $json.vehicle?.model].filter(Boolean)
  },
  actions: [
    'Guardar segmento del comprador',
    'Comparar diariamente contra nuevos vehiculos activos',
    'Enviar email cuando exista match',
    'Usar demanda acumulada para recomendar captacion de stock'
  ],
  received_event: $json
}}];

return [{ json: {
  ok: true,
  route: 'vehicle_approved',
  title: 'Vehiculo aprobado y publicado',
  client_demo_summary: 'Cuando se aprueba una unidad, el showroom recibe confirmacion y el equipo puede activar promocion, SEO y alertas a compradores.',
  publication: {
    dealer_id: $json.dealer_id,
    vehicle_id: $json.vehicle_id,
    vehicle: $json.vehicle,
    status: 'active'
  },
  actions: [
    'Notificar al showroom',
    'Enviar alertas a compradores compatibles',
    'Marcar unidad para newsletter o redes si es destacable',
    'Registrar fecha de publicacion'
  ],
  received_event: $json
}}];

return [{ json: {
  ok: true,
  route: 'vehicle_rejected',
  title: 'Vehiculo rechazado con feedback',
  client_demo_summary: 'Si una ficha no cumple criterio, el workflow devuelve feedback accionable al showroom sin romper la experiencia.',
  rejection: {
    dealer_id: $json.dealer_id,
    vehicle_id: $json.vehicle_id,
    reason: $json.raw_data?.reason || 'Pendiente de completar por el equipo editorial'
  },
  actions: [
    'Enviar motivo de rechazo al showroom',
    'Crear tarea de correccion',
    'Mantener vehiculo como borrador',
    'Reabrir revision cuando el dealer actualice la ficha'
  ],
  received_event: $json
}}];

return [{ json: {
  ok: false,
  route: 'unknown_event',
  title: 'Evento no reconocido',
  client_demo_summary: 'Los eventos desconocidos se registran para revision, sin romper el flujo principal.',
  actions: [
    'Registrar payload',
    'Avisar a operaciones si se repite',
    'Decidir si se incorpora como nuevo caso de uso'
  ],
  received_event: $json
}}];
